-- hrm.tg_overtime_entries_rules: An overtime entry keeps its employment and day, is removed only while worked out and unclaimed, gets approved minutes only on approval (within the minutes asked for), and never changes once rejected, converted to comp-off or paid; refused with constraint ck_overtime_entries_rules.
create or replace function hrm.tg_overtime_entries_rules() returns trigger
language plpgsql as $fn$
begin
    if tg_op = 'DELETE' then
        if old.status <> 'calculated' or old.workflow_instance_id is not null then
            raise exception 'overtime entry %: only an unclaimed worked-out entry is removed', old.id
                using errcode = '23514', constraint = 'ck_overtime_entries_rules';
        end if;
        return old;
    end if;
    if new.minutes < 0 or (new.approved_minutes is not null and new.approved_minutes < 0) or (new.requested_minutes is not null and new.requested_minutes < 1)
       or (new.approved_minutes is not null and new.requested_minutes is not null and new.approved_minutes > new.requested_minutes)
       or (new.status in ('approved', 'paid', 'converted_to_comp_off') and new.approved_minutes is null)
       or new.rate_multiplier < 0 then
        raise exception 'overtime entry %: minutes or multiplier out of rule', new.id
            using errcode = '23514', constraint = 'ck_overtime_entries_rules';
    end if;
    if tg_op = 'INSERT' then
        if new.approved_minutes is not null or new.status not in ('calculated', 'submitted') then
            raise exception 'overtime entry %: a new entry is worked out or asked for', new.id
                using errcode = '23514', constraint = 'ck_overtime_entries_rules';
        end if;
        return new;
    end if;
    -- The comp-off entry of a converted entry is filled in once by the leave engine when it posts the earning; nothing else changes.
    if old.status = 'converted_to_comp_off' and old.comp_off_entry_id is null and new.comp_off_entry_id is not null
       and (to_jsonb(new) - array['comp_off_entry_id', 'updated_at', 'updated_by', 'row_version'])
           = (to_jsonb(old) - array['comp_off_entry_id', 'updated_at', 'updated_by', 'row_version']) then
        return new;
    end if;
    if old.status in ('rejected', 'converted_to_comp_off', 'paid')
       or new.employment_id <> old.employment_id or new.company_id <> old.company_id or new.work_date <> old.work_date
       or (new.approved_minutes is distinct from old.approved_minutes and not (old.status = 'submitted' and new.status = 'approved')) then
        raise exception 'overtime entry %: a decided entry never changes; approved minutes are set by the approval', old.id
            using errcode = '23514', constraint = 'ck_overtime_entries_rules';
    end if;
    return new;
end
